// RotateAllLeft rotates each element of x left by shift bits.
//
//	z[i] = rotateLeft(x[i], shift)
//
// Emulated
func (x Uint16x8) RotateAllLeft(shift uint64) (z Uint16x8) {
	shift = shift & (16 - 1)
	nshift := 16 - shift
	return x.ShiftAllLeft(shift).Or(x.ShiftAllRight(nshift))
}

